begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','knowledge_ingestions','immutable ingestions exist');
select has_function('public','request_knowledge_ingestion',array['uuid','uuid','uuid','integer'],'manager enqueue exists');
insert into public.organizations(id,name,slug) values('a5000000-0000-4000-8000-000000000001','Ingestion fixture','ingestion-050');
insert into auth.users(id) values('b5000000-0000-4000-8000-000000000001'),('b5000000-0000-4000-8000-000000000002');
insert into public.staff_profiles(user_id,organization_id,role) values('b5000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','manager'),('b5000000-0000-4000-8000-000000000002','a5000000-0000-4000-8000-000000000001','staff');
insert into public.knowledge_sources(id,organization_id,version,document) values('c5000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001',1,'{"name":"Fixture","kind":"text","text":"Fixture knowledge","url":null,"authority":"business","productIds":[],"topics":["service"],"freshnessHours":1,"active":true}');
create function pg_temp.enqueue_source(ver integer default 1) returns uuid language sql as $$select public.request_knowledge_ingestion('a5000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001',ver)$$;
select throws_ok($$select public.request_knowledge_ingestion('a5000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000002','c5000000-0000-4000-8000-000000000001',1)$$,'42501','INGESTION_FORBIDDEN','staff cannot enqueue');
select lives_ok($$select pg_temp.enqueue_source()$$,'manager requests refresh');
select is(pg_temp.enqueue_source(),pg_temp.enqueue_source(),'same source version cycle deduplicates');
select is((select count(*) from public.business_jobs where organization_id='a5000000-0000-4000-8000-000000000001'),1::bigint,'one durable job');
select is((select max_attempts from public.business_jobs where organization_id='a5000000-0000-4000-8000-000000000001'),3,'retry bound three');
update public.business_jobs set available_at='1970-01-01' where organization_id='a5000000-0000-4000-8000-000000000001';
select isnt(coalesce((select kind from public.claim_business_job('d5000000-0000-4000-8000-000000000001')),''),'knowledge_ingest','generic business worker cannot consume dedicated ingestion jobs');
update public.business_jobs set status='running',attempts=1,lease_owner='d5000000-0000-4000-8000-000000000001',lease_token='e5000000-0000-4000-8000-000000000001',lease_expires_at=clock_timestamp()+interval '1 minute',attempt_started_at=clock_timestamp() where organization_id='a5000000-0000-4000-8000-000000000001';
create function pg_temp.publish_source(chunks jsonb default '["Fixture knowledge"]',token uuid default 'e5000000-0000-4000-8000-000000000001') returns boolean language sql as $$select public.publish_knowledge_ingestion((select job_id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' order by source_version desc,refresh_cycle desc limit 1),'d5000000-0000-4000-8000-000000000001',token,repeat('a',64),chunks,null,'text/plain')$$;
select is(pg_temp.publish_source('["Text"]',gen_random_uuid()),false,'wrong lease cannot publish');
select throws_ok($$select pg_temp.publish_source('[null]')$$,'22023','INGESTION_INVALID','invalid chunk rejected');
select is((select count(*) from public.knowledge_ingestions where source_id='c5000000-0000-4000-8000-000000000001'),0::bigint,'invalid publish leaves no ingestion');
select is(pg_temp.publish_source(),true,'fenced publish succeeds');
select is(pg_temp.publish_source(),true,'publish replay idempotent');
select is((select count(*) from public.knowledge_chunks c join public.knowledge_ingestions i on i.id=c.ingestion_id where i.source_id='c5000000-0000-4000-8000-000000000001'),1::bigint,'atomic one chunk set');
select is(public.read_current_knowledge('a5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001')->'chunks','["Fixture knowledge"]'::jsonb,'fresh source readable');
select is(public.read_current_knowledge(gen_random_uuid(),'c5000000-0000-4000-8000-000000000001'),null::jsonb,'foreign organization blocked');
select is(public.fail_knowledge_ingestion((select job_id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001'),'d5000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','private secret error'),true,'failure recorded with safe code');
select is((select last_error from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001'),'ingestion_failed','raw error discarded');
select is(public.read_current_knowledge('a5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001'),null::jsonb,'failed refresh cannot serve prior content');
select is(pg_temp.publish_source(),true,'ambiguous publish retry reconciles existing snapshot');
select ok(public.read_current_knowledge('a5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001') is not null,'successful retry clears prior failure');
select throws_ok($$update public.knowledge_chunks set body='bad' where ingestion_id=pg_temp.enqueue_source()$$,'55000',null,'published chunks immutable');
select ok(not has_table_privilege('anon','public.knowledge_chunks','SELECT'),'anonymous cannot read chunks');
select ok(not has_table_privilege('service_role','public.knowledge_chunks','INSERT'),'service cannot bypass publish');
update public.knowledge_sources set version=2 where id='c5000000-0000-4000-8000-000000000001';
select is(public.read_current_knowledge('a5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001'),null::jsonb,'edited source immediately invalidates old evidence');
select is(pg_temp.publish_source(),false,'source changed during ingestion blocks publish');
select lives_ok($$select pg_temp.enqueue_source(2)$$,'new version enqueues independently');
update public.business_jobs set status='running',attempts=1,lease_owner='d5000000-0000-4000-8000-000000000001',lease_token='e5000000-0000-4000-8000-000000000001',lease_expires_at=clock_timestamp()+interval '1 minute',attempt_started_at=clock_timestamp()-interval '2 hours' where id=(select job_id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2);
select is(pg_temp.publish_source(),true,'publish retains historical fetch instant');
select is(public.read_current_knowledge('a5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001'),null::jsonb,'expired ingestion not retrievable');
select is(public.finish_business_job((select job_id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2),'d5000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','handler_failed'),true,'failed attempt queued with backoff');
select is((select status from public.business_jobs where entity_id=(select id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2)),'queued','retry queued');
update public.business_jobs set available_at='1970-01-01' where entity_id=(select id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2);
select is((select attempts from public.claim_knowledge_ingestion('d5000000-0000-4000-8000-000000000001')),2,'dedicated worker claims second attempt');
select public.finish_business_job(id,lease_owner,lease_token,'handler_failed') from public.business_jobs where entity_id=(select id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2);
update public.business_jobs set available_at='1970-01-01' where entity_id=(select id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2);
select is((select attempts from public.claim_knowledge_ingestion('d5000000-0000-4000-8000-000000000001')),3,'third attempt is last');
select public.finish_business_job(id,lease_owner,lease_token,'handler_failed') from public.business_jobs where entity_id=(select id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2);
select is((select status from public.business_jobs where entity_id=(select id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=2)),'dead','retry exhaustion deadletters');
update public.knowledge_sources set version=3,updated_at='1970-01-01' where id='c5000000-0000-4000-8000-000000000001';
select public.enqueue_due_knowledge();
select is((select count(*) from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=3),1::bigint,'scheduler enqueues new saved version');
select public.enqueue_due_knowledge();
select is((select count(*) from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=3),1::bigint,'scheduler deduplicates pending cycle');
update public.business_jobs set status='running',attempts=1,lease_owner='d5000000-0000-4000-8000-000000000001',lease_token='e5000000-0000-4000-8000-000000000001',lease_expires_at=clock_timestamp()+interval '1 minute',attempt_started_at=clock_timestamp() where entity_id=(select id from public.knowledge_ingestion_runs where source_id='c5000000-0000-4000-8000-000000000001' and source_version=3);
create function pg_temp.reject_ingestion_audit() returns trigger language plpgsql as $$begin raise exception 'ingestion_audit_failure'; end$$;
create trigger ingestion_audit_fixture before insert on public.audit_events for each row execute function pg_temp.reject_ingestion_audit();
select throws_ok($$select pg_temp.publish_source()$$,'P0001','ingestion_audit_failure','audit failure rolls back publication');
select is((select count(*) from public.knowledge_ingestions where source_id='c5000000-0000-4000-8000-000000000001'),2::bigint,'failed version swap leaves no partial ingestion');
select is((select count(*) from public.knowledge_chunks c join public.knowledge_ingestions i on i.id=c.ingestion_id where i.source_id='c5000000-0000-4000-8000-000000000001'),2::bigint,'chunks rollback with publication');
update public.knowledge_sources set document=document||'{"active":false}' where id='c5000000-0000-4000-8000-000000000001';
select is(public.read_current_knowledge('a5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001'),null::jsonb,'disabled ingestion not retrievable');
select is(pg_temp.publish_source(),false,'disabled source cannot publish');
select throws_ok($$select pg_temp.enqueue_source(2)$$,'40001','INGESTION_CONFLICT','disabled source cannot enqueue');
select is((select count(*) from public.knowledge_ingestions where source_id='c5000000-0000-4000-8000-000000000001'),2::bigint,'old versions retained');
update public.staff_profiles set active=false where user_id='b5000000-0000-4000-8000-000000000001';
select throws_ok($$select public.knowledge_ingestion_status('a5000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001')$$,'42501','INGESTION_FORBIDDEN','fresh manager permission on status');
select * from finish();
rollback;
